From 81f3abc0302d41c5f175a36c9af5babfc107f8d2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:02:37 +0100
Subject: [PATCH] applets/appmenu: show a Window menu for windows without a
 menu

The Global Menu stayed empty for windows that don't export a menu, or
export an empty one. It now shows a Window menu for them with the same
window management actions KWin's own window menu offers.

BUG: 481628
---
 applets/appmenu/appmenumodel.cpp | 169 ++++++++++++++++++++++++++++++-
 applets/appmenu/appmenumodel.h   |  20 ++++
 2 files changed, 185 insertions(+), 4 deletions(-)

diff --git a/applets/appmenu/appmenumodel.cpp b/applets/appmenu/appmenumodel.cpp
index e91d858062..c91dc75496 100644
--- a/applets/appmenu/appmenumodel.cpp
+++ b/applets/appmenu/appmenumodel.cpp
@@ -23,6 +23,7 @@

 #include <abstracttasksmodel.h>
 #include <dbusmenuimporter.h>
+#include <virtualdesktopinfo.h>

 class KDBusMenuImporter : public DBusMenuImporter
 {
@@ -49,12 +50,14 @@ AppMenuModel::AppMenuModel(QObject *parent)
     connect(m_tasksModel,
             &TaskManager::TasksModel::dataChanged,
             [this](const QModelIndex &topLeft, const QModelIndex &bottomRight, const QList<int> &roles = QList<int>()) {
-                Q_UNUSED(topLeft)
-                Q_UNUSED(bottomRight)
                 if (roles.contains(TaskManager::AbstractTasksModel::ApplicationMenuObjectPath)
                     || roles.contains(TaskManager::AbstractTasksModel::ApplicationMenuServiceName) || roles.isEmpty()) {
                     onActiveWindowChanged();
                 }
+                if (m_windowMenuTask.isValid() && m_windowMenuTask.parent() == topLeft.parent() && m_windowMenuTask.row() >= topLeft.row()
+                    && m_windowMenuTask.row() <= bottomRight.row()) {
+                    updateWindowMenu();
+                }
             });
     connect(m_tasksModel, &TaskManager::TasksModel::activityChanged, this, &AppMenuModel::onActiveWindowChanged);
     connect(m_tasksModel, &TaskManager::TasksModel::virtualDesktopChanged, this, &AppMenuModel::onActiveWindowChanged);
@@ -223,6 +226,160 @@ void AppMenuModel::onActiveWindowChanged()
     const QString objectPath = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuObjectPath).toString();
     const QString serviceName = m_tasksModel->data(activeTaskIndex, TaskManager::AbstractTasksModel::ApplicationMenuServiceName).toString();
     updateApplicationMenu(serviceName, objectPath);
+
+    if (m_serviceName.isEmpty()) {
+        showWindowMenu(activeTaskIndex);
+    }
+}
+
+void AppMenuModel::showWindowMenu(const QModelIndex &task)
+{
+    m_windowMenuTask = task;
+    if (!m_windowMenuTask.isValid()) {
+        if (m_menu && m_menu == m_windowMenu.get()) {
+            m_menu = nullptr;
+            setMenuAvailable(false);
+            setVisible(false);
+            Q_EMIT modelNeedsUpdate();
+        }
+        return;
+    }
+
+    if (!m_windowMenu) {
+        createWindowMenu();
+    }
+    updateWindowMenu();
+
+    if (m_menu != m_windowMenu.get()) {
+        m_menu = m_windowMenu.get();
+        setMenuAvailable(true);
+        setVisible(true);
+        Q_EMIT modelNeedsUpdate();
+    }
+}
+
+void AppMenuModel::createWindowMenu()
+{
+    using namespace TaskManager;
+
+    m_virtualDesktopInfo = new VirtualDesktopInfo(this);
+    connect(m_virtualDesktopInfo, &VirtualDesktopInfo::numberOfDesktopsChanged, this, &AppMenuModel::updateWindowMenu);
+
+    m_windowMenu = std::make_unique<QMenu>();
+    auto windowMenu = new QMenu(i18nc("@title:menu", "&Window"), m_windowMenu.get());
+    m_windowMenu->addMenu(windowMenu);
+
+    auto addAction =
+        [this, windowMenu](const QString &text, const QString &iconName, int enabledRole, int checkedRole, void (TasksModel::*request)(const QModelIndex &)) {
+            QAction *action = windowMenu->addAction(QIcon::fromTheme(iconName), text);
+            action->setCheckable(checkedRole != -1);
+            connect(action, &QAction::triggered, this, [this, request] {
+                if (m_windowMenuTask.isValid()) {
+                    (m_tasksModel->*request)(m_windowMenuTask);
+                }
+            });
+            m_windowActions.append({action, enabledRole, checkedRole});
+        };
+
+    addAction(i18nc("@action:inmenu", "Mi&nimize"),
+              QStringLiteral("window-minimize"),
+              AbstractTasksModel::IsMinimizable,
+              -1,
+              &TasksModel::requestToggleMinimized);
+    addAction(i18nc("@action:inmenu", "Ma&ximize"),
+              QStringLiteral("window-maximize"),
+              AbstractTasksModel::IsMaximizable,
+              AbstractTasksModel::IsMaximized,
+              &TasksModel::requestToggleMaximized);
+    addAction(i18nc("@action:inmenu", "&Fullscreen"),
+              QStringLiteral("view-fullscreen"),
+              AbstractTasksModel::IsFullScreenable,
+              AbstractTasksModel::IsFullScreen,
+              &TasksModel::requestToggleFullScreen);
+    windowMenu->addSeparator();
+    addAction(i18nc("@action:inmenu", "&Move"), QStringLiteral("transform-move"), AbstractTasksModel::IsMovable, -1, &TasksModel::requestMove);
+    addAction(i18nc("@action:inmenu", "&Resize"), QStringLiteral("transform-scale"), AbstractTasksModel::IsResizable, -1, &TasksModel::requestResize);
+    windowMenu->addSeparator();
+    addAction(i18nc("@action:inmenu", "Keep &Above Others"),
+              QStringLiteral("window-keep-above"),
+              -1,
+              AbstractTasksModel::IsKeepAbove,
+              &TasksModel::requestToggleKeepAbove);
+    addAction(i18nc("@action:inmenu", "Keep &Below Others"),
+              QStringLiteral("window-keep-below"),
+              -1,
+              AbstractTasksModel::IsKeepBelow,
+              &TasksModel::requestToggleKeepBelow);
+
+    auto desktopsMenu = new QMenu(i18nc("@title:menu", "Move to &Desktop"), windowMenu);
+    desktopsMenu->setIcon(QIcon::fromTheme(QStringLiteral("virtual-desktops")));
+    windowMenu->addMenu(desktopsMenu);
+    m_windowActions.append({desktopsMenu->menuAction(), AbstractTasksModel::IsVirtualDesktopsChangeable, -1});
+    connect(desktopsMenu, &QMenu::aboutToShow, this, [this, desktopsMenu] {
+        desktopsMenu->clear();
+        if (!m_windowMenuTask.isValid()) {
+            return;
+        }
+
+        const QVariantList taskDesktops = m_tasksModel->data(m_windowMenuTask, AbstractTasksModel::VirtualDesktops).toList();
+        const bool onAllDesktops = m_tasksModel->data(m_windowMenuTask, AbstractTasksModel::IsOnAllVirtualDesktops).toBool();
+
+        QAction *allDesktops = desktopsMenu->addAction(i18nc("@action:inmenu", "&All Desktops"));
+        allDesktops->setCheckable(true);
+        allDesktops->setChecked(onAllDesktops);
+        connect(allDesktops, &QAction::triggered, this, [this] {
+            if (m_windowMenuTask.isValid()) {
+                m_tasksModel->requestVirtualDesktops(m_windowMenuTask, {});
+            }
+        });
+        desktopsMenu->addSeparator();
+
+        const QVariantList desktopIds = m_virtualDesktopInfo->desktopIds();
+        const QStringList desktopNames = m_virtualDesktopInfo->desktopNames();
+        for (int i = 0; i < desktopIds.count(); ++i) {
+            const QVariant desktopId = desktopIds.at(i);
+            const QString text = i < 9 ? i18nc("1 = number of desktop, 2 = name of desktop", "&%1 %2", i + 1, desktopNames.value(i))
+                                       : i18nc("1 = number of desktop, 2 = name of desktop", "%1 %2", i + 1, desktopNames.value(i));
+            QAction *action = desktopsMenu->addAction(text);
+            action->setCheckable(true);
+            action->setChecked(!onAllDesktops && taskDesktops.contains(desktopId));
+            connect(action, &QAction::triggered, this, [this, desktopId] {
+                if (m_windowMenuTask.isValid()) {
+                    m_tasksModel->requestVirtualDesktops(m_windowMenuTask, {desktopId});
+                }
+            });
+        }
+
+        desktopsMenu->addSeparator();
+        QAction *newDesktop = desktopsMenu->addAction(QIcon::fromTheme(QStringLiteral("list-add")), i18nc("@action:inmenu", "&New Desktop"));
+        connect(newDesktop, &QAction::triggered, this, [this] {
+            if (m_windowMenuTask.isValid()) {
+                m_tasksModel->requestNewVirtualDesktop(m_windowMenuTask);
+            }
+        });
+    });
+
+    windowMenu->addSeparator();
+    addAction(i18nc("@action:inmenu", "&Close"), QStringLiteral("window-close"), AbstractTasksModel::IsClosable, -1, &TasksModel::requestClose);
+}
+
+void AppMenuModel::updateWindowMenu()
+{
+    if (!m_windowMenu || !m_windowMenuTask.isValid()) {
+        return;
+    }
+
+    for (const WindowAction &windowAction : std::as_const(m_windowActions)) {
+        if (windowAction.enabledRole != -1) {
+            windowAction.action->setEnabled(m_tasksModel->data(m_windowMenuTask, windowAction.enabledRole).toBool());
+        }
+        if (windowAction.checkedRole != -1) {
+            windowAction.action->setChecked(m_tasksModel->data(m_windowMenuTask, windowAction.checkedRole).toBool());
+        }
+        if (windowAction.action->menu()) {
+            windowAction.action->setVisible(m_virtualDesktopInfo->numberOfDesktops() > 1);
+        }
+    }
 }

